/**
 * The tally's own suite. It reads the live tally of every suite before it
 * (RT05), so it runs last, in the parent, after every worker's lines are in.
 */
const TALLY_SUITE = 'run-tally';

/**
 * The suites started first, longest first: the ones that build and render
 * rigs through rig-c, which held 96 % of a sequential run's wall time in
 * each of three runs on one machine (the per-suite table in the pull request
 * that closed issue #99). The longest of them alone bounds a concurrent run,
 * and started in print order they would begin last. Scheduling only — the run prints, counts and judges in `SUITES`
 * order whatever this says, and a name here that is no suite's is refused
 * (`dispatchOrder`), because a misspelt name would quietly cost the time it
 * exists to buy.
 */
const STARTED_FIRST: readonly string[] = ['readme-loop', 'chain', 'build', 'check', 'scene', 'assemble-examples', 'propose', 'rig', 'auto-mesh-examples', 'auto-motion', 'build-cost', 'auto-mesh'];

/** The argument that makes this file run one suite, or one unit of a split suite, as a worker, for the parent run, and nothing else. */
/** A sampled process identity: PID reuse must not retain the former holder. */
interface SelftestRssRow { pid: number; parent: number; start: string; bytes: number }

/** Sum discovered descendants, retaining an orphan only while its identity is unchanged. */
function selftestFamilyRss(rows: readonly SelftestRssRow[], known: Map<number, string>): number {
  const family = new Map<number, string>();
  for (const row of rows) if (known.get(row.pid) === row.start) family.set(row.pid, row.start);
  let grew = true;
  while (grew) {
    grew = false;
    for (const row of rows) if (!family.has(row.pid) && family.has(row.parent)) {
      family.set(row.pid, row.start);
      grew = true;
    }
  }
  known.clear();
  for (const [pid, start] of family) known.set(pid, start);
  return rows.reduce((sum, row) => sum + (family.has(row.pid) ? row.bytes : 0), 0);
}

/** Linux /proc status RSS in KiB; shared pages count once per PID.
 * This samples the selftest family, excluding an ancestor package runner. A blocked event
 * loop or a child shorter than 200 ms can be missed; this line is not a memory guard.
 */
/** Node-compatible process.resourceUsage().maxRSS is KiB, not Bun.Subprocess bytes.
 * The own-process kernel high-water mark and the sampled descendants answer different questions.
 * https://nodejs.org/api/process.html#processresourceusage
 */
function selftestPeakFinish(familyText: () => string, write: (text: string) => void = (text) => { process.stderr.write(text); }): () => void {
  let finished = false;
  return (): void => {
    if (finished) return;
    finished = true;
    let own = 'self_max_rss_kib=unavailable';
    try { own = 'self_max_rss_kib=' + process.resourceUsage().maxRSS; } catch { /* not supported by every runtime */ }
    write('selftest peak (stderr, never tallied): ' + own + '; ' + familyText() + '\n');
  };
}
function startSelftestPeak(): () => void {
  if (process.platform !== 'linux' || !existsSync('/proc/self/stat')) {
    return selftestPeakFinish(() => 'family RSS unavailable; Linux /proc is required');
  }
  const identity = (text: string): readonly [number, string] => {
    const fields = text.slice(text.lastIndexOf(')') + 2).split(/\s+/);
    return [Number(fields[1]), fields[19]];
  };
  const [, rootStart] = identity(readFileSync('/proc/self/stat', 'utf8'));
  const known = new Map<number, string>([[process.pid, rootStart]]);
  let peak = 0;
  let samples = 0;
  let unreadable = 0;
  const sample = (): void => {
    const rows: SelftestRssRow[] = [];
    for (const entry of readdirSync('/proc')) {
      if (!/^\d+$/.test(entry)) continue;
      try {
        const [parent, start] = identity(readFileSync('/proc/' + entry + '/stat', 'utf8'));
        const rss = /^VmRSS:\s+(\d+)\s+kB$/m.exec(readFileSync('/proc/' + entry + '/status', 'utf8'));
        rows.push({ pid: Number(entry), parent, start, bytes: rss === null ? 0 : Number(rss[1]) * 1024 });
      } catch {
        unreadable++;
      }
    }
    peak = Math.max(peak, selftestFamilyRss(rows, known));
    samples++;
  };
  sample();
  const timer = setInterval(sample, 200);
  timer.unref();
  return selftestPeakFinish(() => {
    clearInterval(timer);
    sample();
    return 'family_rss_bytes=' + peak + '; interval_ms=200; samples=' + samples + '; unreadable_proc_entries=' + unreadable + '; method=linux-proc-status-summed-rss';
  });
}

const WORKER_FLAG = '--suite-worker';

/**
 * Issue #395: the suites whose work is one block per public example, which a sharded run splits into one unit per
 * tracked example (`<suite>@<example>`) and one closing unit (`<suite>@end`). The first unit opens the suite's section
 * and runs what comes before the examples; the closing unit runs what comes after them. Each unit is its own process,
 * so a unit that needs another example's build (the chain's public scenes) builds it itself. Whole, as `bun run
 * selftest` runs it, such a suite prints those same blocks in that order, so the units' lines put end to end in
 * {@link suiteUnits} order are the whole suite's.
 */
const SPLIT_SUITES: readonly string[] = ['assemble-examples', 'chain', 'readme-loop'];

/** What joins a split suite's key to the example its unit runs, and the closing unit's name. */
const UNIT_MARK = '@';
const END_UNIT = 'end';

/**
 * The units of one suite, in the order their lines are printed: the suite itself, or for a split suite one unit per
 * tracked example (`exampleKeys().all`, fetched or not — a unit whose example was not fetched prints nothing) and the
 * closing unit.
 */
function suiteUnits(key: string, examples: readonly string[]): string[] {
  return SPLIT_SUITES.includes(key) ? [...examples.map((e) => `${key}${UNIT_MARK}${e}`), `${key}${UNIT_MARK}${END_UNIT}`] : [key];
}

/** Every unit of a run over `keys`, in print order; a string names why there is no such list. */
function runUnits(keys: readonly string[], examples: readonly string[]): string[] | string {
  if (examples.includes(END_UNIT)) return `an example is named "${END_UNIT}", which is the name of every split suite's closing unit`;
  const unknown = SPLIT_SUITES.filter((k) => !keys.includes(k));
  if (unknown.length > 0) return `the split suite(s) ${unknown.map((k) => `"${k}"`).join(', ')} are no suite of this run`;
  return keys.flatMap((k) => suiteUnits(k, examples));
}

/**
 * The CI shards (issue #395): each is one job of `.github/workflows/ci.yml` running `--shard <name>`, and `test`
 * merges their records. Every unit of the run is in exactly one shard (`RT09`), and a shard starts its units in the
 * order listed here, longest first. The assignment balances the per-unit worker times the run's clock line printed;
 * the table and the estimate are in the pull request that closed issue #395. A new example adds a unit to each split
 * suite, and every run fails `RT09` until each of them is placed here.
 */
const SHARDS: ReadonlyArray<readonly [string, readonly string[]]> = [
  ['1', ['check']],
  ['2', ['readme-loop@wind', 'chain@scarf', 'chain@wind', 'rig', 'influence', 'chain-inherit', 'readme-loop@reference-demo', 'readme-loop@reference-sample', 'readme-loop@scarf', 'assemble-examples@demo', 'assemble-examples@reference-demo', 'assemble-examples@reference-sample', 'auto-motion', 'propose', 'readme-loop@end', 'auto-mesh-examples', 'inputs-examples', 'build-cost', 'loop', 'assemble', 'subset-cover', 'foot-ownership', 'limb-slots', 'limb-layout', 'front-slot', 'arm-split-upgrade', 'alternate-tips', 'alternate-layers', 'contour-wiring', 'config', 'config-write', 'core-pointer', 'structure', 'inputs', 'plausibility', 'skeleton', 'assemble-examples@end', 'winding', 'fetch-examples', 'prompt', 'layers-psd', 'parts', 'raster-components', 'raster-morph', 'raster-blur', 'raster-poly', 'raster-composite', 'requirements']],
  ['3', ['readme-loop@demo', 'chain@end', 'build', 'chain@demo', 'chain@reference-demo', 'chain@reference-sample', 'cli', 'assemble-examples@scarf', 'assemble-examples@wind', 'mesh-draft', 'mesh-stats', 'remesh', 'retune', 'scene', 'tree', 'auto-mesh', 'corpus', 'propose-corpus', 'keypoints', 'contour', 'comfy', 'diagnostics', 'painting', 'sheet', 'layers-wrapper', 'raster-resize', 'raster-warp', 'png']],
];

/**
 * The part of a split suite this worker runs (issue #395): null when it runs the whole suite, else the example its
 * unit names or {@link END_UNIT}. Set once, by {@link workerMain}, before the suite starts.
 */
let unitPart: string | null = null;

/** What one run of a split suite does: open the section and run what precedes the examples, run one example, run what follows them. */
interface SplitPart {
  head: boolean;
  has: (example: string) => boolean;
  tail: boolean;
}

/** {@link SplitPart} for the suite `key` in this worker: everything when the suite runs whole, else its unit's share. */
function splitPart(key: string): SplitPart {
  const part = unitPart;
  if (part === null) return { head: true, has: () => true, tail: true };
  return { head: suiteUnits(key, exampleKeys().all)[0] === `${key}${UNIT_MARK}${part}`, has: (e) => e === part, tail: part === END_UNIT };
}

/** A `say` that prints and counts nothing: what a unit runs to reach a value another unit reports. */
const quietSay = (): void => {};

/**
 * The environment variables renamed with the package: each pair is the name
 * read first and the former name it falls back to. `jobs` sets how many workers
 * run at once (the machine's available parallelism when neither is set);
 * `corpus` names the extra suite's corpus when `--corpus` does not.
 */
const ENV_TWINS = {
  corpus: ['RIG_PARTS_CORPUS', 'SPINE_PARTS_CORPUS'],
  jobs: ['RIG_PARTS_SELFTEST_JOBS', 'SPINE_PARTS_SELFTEST_JOBS'],
} as const satisfies Record<string, readonly [string, string]>;

/** The first of a twin's two names that is set to something other than the empty string, and its value; null when neither is. */
function envTwin(env: Readonly<Record<string, string | undefined>>, twin: readonly [string, string]): { name: string; value: string } | null {
  for (const name of twin) {
    const value = env[name];
    if (value !== undefined && value !== '') return { name, value };
  }
  return null;
}

/** The order workers are started in: `first` in its order, then every other suite in `keys` order. A string names what is wrong. */
function dispatchOrder(keys: readonly string[], first: readonly string[]): string[] | string {
  const unknown = first.filter((k) => !keys.includes(k));
  if (unknown.length > 0) return `the suite(s) ${unknown.map((k) => `"${k}"`).join(', ')} are started first and are no suite of this run`;
  const twice = first.filter((k, i) => first.indexOf(k) !== i);
  if (twice.length > 0) return `the suite(s) ${twice.map((k) => `"${k}"`).join(', ')} are started first twice`;
  return [...first, ...keys.filter((k) => !first.includes(k))];
}

/** What one worker left behind: its exit, everything it printed, and the result file it wrote (null when it wrote none). */
interface WorkerRun {
  key: string;
  status: number | null;
  stdout: string;
  stderr: string;
  result: string | null;
}

/**
 * Hand one suite's worker to the tally as if the suite had run here: print
 * every line it printed, in order, through `print` (which the tally observes),
 * and return the failure count it handed back. A worker that cannot account
 * for its suite — none ran it, it wrote no result, a result for another
 * suite, a result it did not exit 0 after — throws, and `RunTally.of` prints
 * that as the suite's `SUITE_CRASHED` FAIL line, as it does for a suite that
 * throws in-process. A suite that threw inside its worker throws its own stack
 * here, after the lines it printed before it threw.
 */
function replayWorker(key: string, run: WorkerRun | undefined, print: (line: string) => void, printErr: (text: string) => void): number | null {
  if (run === undefined) throw new Error(`no worker ran the suite "${key}", so nothing it would have printed was read`);
  const lines = run.stdout === '' ? [] : run.stdout.replace(/\n$/, '').split('\n');
  for (const line of lines) print(line);
  if (run.stderr !== '') printErr(run.stderr);
  const tail = run.stderr.trim().split('\n').slice(-3).join(' | ');
  if (run.result === null) throw new Error(`the worker for the suite "${key}" exited ${run.status ?? 'on a signal'} without writing its result${tail === '' ? '' : `: ${tail}`}`);
  let record: { key?: unknown; returned?: unknown; crash?: unknown };
  try {
    record = JSON.parse(run.result) as typeof record;
  } catch {
    throw new Error(`the worker for the suite "${key}" wrote a result that is not JSON: ${run.result.slice(0, 80)}`);
  }
  if (record.key !== key) throw new Error(`the worker for the suite "${key}" wrote the result of the suite ${JSON.stringify(record.key)}`);
  if (typeof record.crash === 'string') {
    const err = new Error(`the suite "${key}" threw in its worker`);
    err.stack = record.crash;
    throw err;
  }
  if (run.status !== 0) throw new Error(`the worker for the suite "${key}" wrote its result and exited ${run.status ?? 'on a signal'}${tail === '' ? '' : `: ${tail}`}`);
  if (record.returned !== null && !(typeof record.returned === 'number' && Number.isInteger(record.returned) && record.returned >= 0)) {
    throw new Error(`the worker for the suite "${key}" handed back ${JSON.stringify(record.returned)}, which is neither a failure count nor null`);
  }
  return record.returned;
}

/**
 * Where the suites the run tallied are not every suite of the run, once each
 * and in order. Empty is agreement. This is what holds the union of what the
 * workers ran to the whole run: a suite dropped from the dispatch is a block
 * missing here, whatever the workers printed.
 */
function suiteSetFaults(tallied: readonly string[], expected: readonly string[]): string[] {
  const faults: string[] = [];
  const missing = expected.filter((k) => !tallied.includes(k));
  const extra = tallied.filter((k) => !expected.includes(k));
  if (missing.length > 0) faults.push(`the suite(s) ${missing.map((k) => `"${k}"`).join(', ')} are suites of this run and were never tallied`);
  if (extra.length > 0) faults.push(`the suite(s) ${extra.map((k) => `"${k}"`).join(', ')} were tallied and are no suite of this run`);
  if (missing.length === 0 && extra.length === 0 && tallied.join('\n') !== expected.join('\n')) faults.push(`the suites were tallied as ${tallied.join(', ')}, not in the order ${expected.join(', ')}`);
  return faults;
}

/**
 * The worker's whole job: run the one suite, or the one unit of a split suite, named after `WORKER_FLAG`, let it
 * print, and write what it handed back under that name.
 */
function workerMain(argv: readonly string[]): void {
  const key = argv[argv.indexOf(WORKER_FLAG) + 1];
  const at = argv.indexOf('--result');
  const result = at === -1 ? undefined : argv[at + 1];
  const mark = key === undefined ? -1 : key.indexOf(UNIT_MARK);
  const suiteKey = mark === -1 ? key : key.slice(0, mark);
  const suite = SUITES.find(([k]) => k === suiteKey);
  const units = runUnits(SUITES.map(([k]) => k), exampleKeys().all);
  const known = mark === -1 || (typeof units !== 'string' && units.includes(key));
  if (suite === undefined || !known || result === undefined) {
    console.error(`selftest: ${WORKER_FLAG} needs one of this run's suites or units and --result <file>; got ${JSON.stringify(key)} and ${JSON.stringify(result)}${typeof units === 'string' ? ` (${units})` : ''}`);
    process.exit(2);
  }
  unitPart = mark === -1 ? null : key.slice(mark + 1);
  let record: { key: string; returned: number | null } | { key: string; crash: string };
  try {
    record = { key, returned: suite[1](corpusDir()) };
  } catch (err) {
    record = { key, crash: (err as Error).stack ?? String(err) };
  }
  writeFileSync(result, JSON.stringify(record));
}

/** How many workers run at once: `ENV_TWINS.jobs` when set, a positive whole number or the run exits 2; else the machine's available parallelism. */
function workerCount(): number {
  const set = envTwin(process.env, ENV_TWINS.jobs);
  if (set === null) return availableParallelism();
  if (!/^[1-9]\d*$/.test(set.value)) {
    console.error(`selftest: ${set.name} is ${JSON.stringify(set.value)}; a positive whole number of workers is required`);
    process.exit(2);
  }
  return Number(set.value);
}

function launchWorker(key: string, corpus: string | null, dir: string): Promise<WorkerRun> {
  const result = join(dir, `${key}.json`);
  const args = [import.meta.path, WORKER_FLAG, key, '--result', result, ...(corpus === null ? [] : ['--corpus', corpus])];
  return new Promise((done) => {
    const out: Buffer[] = [];
    const err: Buffer[] = [];
    const child = spawn(process.execPath, args, { cwd: process.cwd(), stdio: ['ignore', 'pipe', 'pipe'] });
    child.stdout.on('data', (b: Buffer) => out.push(b));
    child.stderr.on('data', (b: Buffer) => err.push(b));
    const finish = (status: number | null, extra: string): void =>
      done({ key, status, stdout: Buffer.concat(out).toString('utf8'), stderr: Buffer.concat(err).toString('utf8') + extra, result: existsSync(result) ? readFileSync(result, 'utf8') : null });
    child.on('error', (e) => finish(null, `could not start the worker: ${e.message}\n`));
    child.on('close', (status) => finish(status, ''));
  });
}

/** Start every suite's worker, `jobs` at a time in `order`; each suite's promise settles when its worker has exited. */
function startWorkers(order: readonly string[], jobs: number, launch: (key: string) => Promise<WorkerRun>): Map<string, Promise<WorkerRun>> {
  const settle = new Map<string, (run: WorkerRun) => void>();
  const runs = new Map<string, Promise<WorkerRun>>();
  for (const key of order) runs.set(key, new Promise<WorkerRun>((done) => settle.set(key, done)));
  let next = 0;
  const lane = async (): Promise<void> => {
    while (next < order.length) {
      const key = order[next++];
      const run = await launch(key);
      settle.get(key)?.(run);
    }
  };
  for (let i = 0; i < Math.min(jobs, order.length); i++) void lane();
  return runs;
}

/**
 * Each worker's wall time, for the run's log (issue #395: the CI log carried no per-suite time, so which suites hold
 * the job's minutes could not be read off it). Written to stderr only: the tally observes stdout, nothing compares
 * stderr, and a time is the one thing two runs of the same tree never agree on. One line per suite in `keys` order:
 * its seconds, then when its worker started and ended, from the parent's start.
 */
function workerClockText(keys: readonly string[], clock: ReadonlyMap<string, readonly [number, number]>, jobs: number, wallMs: number): string {
  const s = (ms: number): string => (ms / 1000).toFixed(1);
  const lines = [`selftest clock (stderr, never tallied): ${jobs} worker(s) at once on ${availableParallelism()} available core(s); every worker done at ${s(wallMs)} s`];
  for (const key of keys) {
    const at = clock.get(key);
    lines.push(at === undefined ? `  clock  ${key}  no worker finished` : `  clock  ${key}  ${s(at[1] - at[0])} s  (+${s(at[0])} .. +${s(at[1])})`);
  }
  return `${lines.join('\n')}\n`;
}

/**
 * Where a partition of the run's units into shards is not every unit once (issue #395): a unit in no shard, a unit
 * placed twice, a name that is no unit, a shard named twice, a shard with no unit. Empty is agreement.
 */
function shardFaults(shards: ReadonlyArray<readonly [string, readonly string[]]>, units: readonly string[]): string[] {
  const faults: string[] = [];
  const names = shards.map(([n]) => n);
  const twiceNamed = [...new Set(names.filter((n, i) => names.indexOf(n) !== i))];
  if (twiceNamed.length > 0) faults.push(`the shard(s) ${twiceNamed.map((n) => `"${n}"`).join(', ')} are named twice`);
  for (const [n, us] of shards) if (us.length === 0) faults.push(`the shard "${n}" holds no unit`);
  const placed = shards.flatMap(([n, us]) => us.map((u) => [n, u] as const));
  for (const u of units) {
    const at = placed.filter(([, x]) => x === u).map(([n]) => `"${n}"`);
    if (at.length === 0) faults.push(`the unit "${u}" is in no shard, so a sharded run would never run it`);
    if (at.length > 1) faults.push(`the unit "${u}" is placed ${at.length} times (shard ${at.join(', ')}), so a sharded run would run it ${at.length} times`);
  }
  const unknown = placed.filter(([, u]) => !units.includes(u));
  if (unknown.length > 0) faults.push(`the shard entr(ies) ${unknown.map(([n, u]) => `"${u}" in shard "${n}"`).join(', ')} are no unit of this run`);
  return faults;
}

/** One unit's worker as a shard recorded it: the run, and when its worker started and ended, in ms from the shard's start. */
interface RecordedUnit extends WorkerRun {
  began: number;
  ended: number;
}

/** One shard's record, as `--record` writes it and `--merge` reads it. */
interface ShardRecord {
  spec: string;
  shard: string;
  jobs: number;
  cores: number;
  units: RecordedUnit[];
}

const SHARD_RECORD_SPEC = 'rig-parts-selftest-shard/1';

/** A shard record read from its text, or what is wrong with it. */
function parseShardRecord(text: string): ShardRecord | string {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return 'not JSON';
  }
  if (typeof raw !== 'object' || raw === null) return 'not a JSON object';
  const r = raw as Partial<ShardRecord>;
  if (r.spec !== SHARD_RECORD_SPEC) return `spec ${JSON.stringify(r.spec ?? null)}; "${SHARD_RECORD_SPEC}" is required`;
  if (typeof r.shard !== 'string' || typeof r.jobs !== 'number' || typeof r.cores !== 'number' || !Array.isArray(r.units)) return 'shard, jobs, cores or units is absent or of the wrong type';
  for (const u of r.units as unknown[]) {
    const x = (typeof u === 'object' && u !== null ? u : {}) as Partial<RecordedUnit>;
    const ok =
      typeof x.key === 'string' &&
      (x.status === null || typeof x.status === 'number') &&
      typeof x.stdout === 'string' &&
      typeof x.stderr === 'string' &&
      (x.result === null || typeof x.result === 'string') &&
      typeof x.began === 'number' &&
      typeof x.ended === 'number';
    if (!ok) return `the unit entry ${JSON.stringify(x.key ?? null)} lacks one of key, status, stdout, stderr, result, began and ended, or holds one of the wrong type`;
  }
  return r as ShardRecord;
}

/**
 * Where a set of shard records is not one run of every unit once (issue #395): a shard with no record or with two, a
 * record for no shard, a record whose units are not its shard's, and — across every record — a unit recorded by no
 * shard or by two, and a recorded unit that is no unit of this run. Empty is agreement, and only then does the merge
 * replay anything.
 */
function recordFaults(records: readonly ShardRecord[], shards: ReadonlyArray<readonly [string, readonly string[]]>, units: readonly string[]): string[] {
  const faults: string[] = [];
  for (const [n] of shards) {
    const count = records.filter((r) => r.shard === n).length;
    if (count === 0) faults.push(`the shard "${n}" left no record`);
    if (count > 1) faults.push(`the shard "${n}" left ${count} records`);
  }
  for (const r of records) {
    const def = shards.find(([n]) => n === r.shard);
    if (def === undefined) {
      faults.push(`a record names the shard "${r.shard}", which is no shard of this run`);
      continue;
    }
    const ran = r.units.map((u) => u.key);
    if ([...ran].sort().join('\n') !== [...def[1]].sort().join('\n')) faults.push(`the shard "${r.shard}" recorded ${ran.join(', ') || 'no unit'}, not its units ${def[1].join(', ')}`);
  }
  const recorded = records.flatMap((r) => r.units.map((u) => [r.shard, u.key] as const));
  for (const u of units) {
    const by = recorded.filter(([, k]) => k === u).map(([s]) => `"${s}"`);
    if (by.length === 0) faults.push(`the unit "${u}" was recorded by no shard, so nothing it would have printed was read`);
    if (by.length > 1) faults.push(`the unit "${u}" was recorded ${by.length} times (shard ${by.join(', ')}), so its lines would be counted ${by.length} times`);
  }
  const strangers = [...new Set(recorded.map(([, k]) => k).filter((k) => !units.includes(k)))];
  if (strangers.length > 0) faults.push(`the record(s) hold ${strangers.map((k) => `"${k}"`).join(', ')}, which are no unit of this run`);
  return faults;
}

/**
 * Hand one suite's units to the tally as if the suite had run here (issue #395): each unit's lines, in `units` order,
 * through {@link replayWorker}, and the sum of their failure counts. A suite that ran whole is its one unit. The units
 * of a suite that had nothing to read all hand back null, and so does the suite; units that disagree throw, as a
 * worker that cannot account for itself does.
 */
function replayUnits(key: string, units: readonly string[], runs: ReadonlyArray<WorkerRun | undefined>, print: (line: string) => void, printErr: (text: string) => void): number | null {
  const values = units.map((u, i) => replayWorker(u, runs[i], print, printErr));
  const counts = values.filter((v): v is number => v !== null);
  if (counts.length === 0) return null;
  if (counts.length < values.length) {
    throw new Error(`the units of the suite "${key}" disagree whether it ran: ${units.filter((_, i) => values[i] === null).join(', ')} handed back null and ${units.filter((_, i) => values[i] !== null).join(', ')} a count`);
  }
  return counts.reduce((sum, v) => sum + v, 0);
}

/** The arguments that run one shard of the units and write its record, and that merge every shard's record into one run (issue #395). */
const SHARD_FLAG = '--shard';
const RECORD_FLAG = '--record';
const MERGE_FLAG = '--merge';

/** `--only <suite>[,<suite>…]` (issue #500): a PARTIAL run of the named suites, which exits 2 when green and is never a verdict. */
const ONLY_FLAG = '--only';
const CORPUS_FLAG = '--corpus';

/** `--summary-json <file>` (issue #725): write a machine-readable summary derived from the same RunTally that prints the console summary. */
const SUMMARY_JSON_FLAG = '--summary-json';
const SUMMARY_JSON_SPEC = 'rig-selftest-summary/1';
const SUMMARY_JSON_TOOL = 'rig-parts';

type SummarySuiteStatus = 'pass' | 'fail' | 'hole' | 'skipped';

interface SummarySuiteEntry {
  suite: string;
  ran: boolean;
  controls: number;
  passed: number;
  failed: number;
  skipped: number;
  status: SummarySuiteStatus;
  reason: string | null;
}

interface SummarySkipEntry {
  suite: string;
  name: string;
  reason: string;
  hole: boolean;
}

interface SummaryHoleEntry {
  suite: string;
  name: string;
  reason: string;
}

interface SelftestSummaryJson {
  spec: string;
  tool: string;
  exit: 0 | 1 | 2;
  partial: boolean;
  only: string[] | null;
  faults: string[];
  totals: {
    suites: number;
    ran: number;
    skipped_suites: number;
    controls: number;
    passed: number;
    failed: number;
    skipped: number;
    holes: number;
  };
  suites: SummarySuiteEntry[];
  skips: SummarySkipEntry[];
  holes: SummaryHoleEntry[];
}

/**
 * Every flag the parent run reads, and the value it takes (issue #500). Each takes exactly one value, and nothing else
 * may stand on the command line: an unknown flag, a stray word, a flag given twice or one with no value is refused by
 * name before any suite starts. Until then the parent read the flags it knew and ignored the rest, so `--suite
 * assemble` and `--only tree` each ran every suite for the length of a whole run and said nothing about the word it had
 * dropped. `--suite-worker` is not here: it is the worker's own command line, which {@link workerMain} reads.
 */
const RUN_FLAGS: ReadonlyArray<readonly [string, string]> = [
  [CORPUS_FLAG, '<dir>'],
  [SHARD_FLAG, '<name>'],
  [RECORD_FLAG, '<file>'],
  [MERGE_FLAG, '<dir>'],
  [ONLY_FLAG, '<suite>[,<suite>…]'],
  [SUMMARY_JSON_FLAG, '<file>'],
];

/** The flags, as the refusal lists them. */
function runFlagsText(flags: ReadonlyArray<readonly [string, string]>): string {
  return flags.map(([f, v]) => `${f} ${v}`).join(', ');
}

/**
 * The parent run's command line read against `flags` (issue #500): each flag's value, or every refusal it holds — a
 * flag that is not one of them, a word that follows no flag, a flag given twice, a flag with no value. Nothing is read
 * generously, because whatever a guess decided would decide which suites a verdict covers.
 */
function readRunArgs(argv: readonly string[], flags: ReadonlyArray<readonly [string, string]>): Map<string, string> | string[] {
  const values = new Map<string, string>();
  const refusals: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    const known = flags.some(([f]) => f === token);
    if (!known) {
      refusals.push(token.startsWith('-') ? `${JSON.stringify(token)} is no flag of this run` : `${JSON.stringify(token)} follows no flag; this run takes no positional argument`);
      continue;
    }
    const value = argv[i + 1];
    if (value === undefined || value.trim() === '' || value.startsWith('--')) {
      refusals.push(`${token} needs a value`);
      continue;
    }
    i++;
    if (values.has(token)) refusals.push(`${token} was given twice`);
    else values.set(token, value);
  }
  return refusals.length > 0 ? refusals : values;
}

/**
 * The suites `--only` names (issue #500), or every refusal it holds: an empty name between its commas, a name given
 * twice, a name that is no suite of this run — which lists the suites, since the caller who misspelt one needs the
 * spelling. `suites` is the run's registry, {@link SUITES} and the tally's own suite, so no second list of names is kept
 * beside it.
 */
function readOnlyList(value: string, suites: readonly string[]): Set<string> | string[] {
  const seen = new Set<string>();
  const refusals: string[] = [];
  const unknown: string[] = [];
  for (const name of value.split(',')) {
    if (name === '') refusals.push(`${ONLY_FLAG} ${value} holds an empty name between its commas`);
    else if (seen.has(name)) refusals.push(`${ONLY_FLAG} ${value} names the suite "${name}" twice`);
    else if (!suites.includes(name)) unknown.push(name);
    seen.add(name);
  }
  if (unknown.length > 0) refusals.push(`${ONLY_FLAG} names ${unknown.map((n) => `"${n}"`).join(', ')}, which ${unknown.length === 1 ? 'is no suite' : 'are no suites'} of this run; the suites are ${suites.join(', ')}`);
  return refusals.length > 0 ? refusals : seen;
}

/** Print every refusal and exit 2, before any suite has started. */
function refuseArgs(refusals: readonly string[]): never {
  for (const r of refusals) console.error(`selftest: ${r}`);
  console.error(`selftest: the flags are ${runFlagsText(RUN_FLAGS)}; a run with none is the whole run`);
  process.exit(2);
}

/**
 * How a run with `--only` ends (issue #500), or null when it is not partial — no flag, or a flag naming every suite,
 * which is the whole run spelled longhand and ends like one. A partial run never prints the summary: green, its last
 * line says it was partial and names what it skipped, and it exits 2; red, it exits 1 as the whole run would, because
 * a red found in part is a red in the whole.
 */
function partialVerdict(ran: readonly string[], skipped: readonly string[], cases: number, failures: number): { code: 1 | 2; err: string | null; out: string } | null {
  if (skipped.length === 0) return null;
  const out =
    `rig-parts selftest: PARTIAL run (${ONLY_FLAG}) — not a verdict on the tree. ${ran.length} suite(s) ran [${ran.join(', ')}] over ${cases} case line(s); ` +
    `${skipped.length} suite(s) were not run [${skipped.join(', ')}]. Run \`bun run selftest\` without ${ONLY_FLAG} before a pull request.`;
  return failures > 0 ? { code: 1, err: `rig-parts selftest: ${failures} control(s) failed`, out } : { code: 2, err: null, out };
}

/** Build the machine-readable summary (issue #725) from the same {@link RunTally} that prints the console summary. */
function buildSummaryJson(
  tally: RunTally,
  only: ReadonlySet<string> | null,
  faults: readonly string[],
  exit: 0 | 1 | 2,
): SelftestSummaryJson {
  const suites: SummarySuiteEntry[] = tally.blocks.map((b) => {
    const passed = b.controls - b.fails;
    const failed = b.fails;
    const skipped = b.skips.length;
    const status: SummarySuiteStatus =
      b.fails > 0 || b.returned > 0
        ? 'fail'
        : b.ran
          ? 'pass'
          : b.skips.some((s) => s.hole)
            ? 'hole'
            : 'skipped';
    const reason = b.ran ? null : (b.skips[0]?.reason ?? null);
    return {
      suite: b.key,
      ran: b.ran,
      controls: b.controls,
      passed,
      failed,
      skipped,
      status,
      reason,
    };
  });
  const skips: SummarySkipEntry[] = tally.blocks.flatMap((b) =>
    b.skips.map((s) => ({
      suite: b.key,
      name: s.name,
      reason: s.reason,
      hole: s.hole,
    })),
  );
  const holes: SummaryHoleEntry[] = skips
    .filter((s) => s.hole)
    .map(({ suite, name, reason }) => ({ suite, name, reason }));
  const ranCount = suites.filter((s) => s.ran).length;
  const skippedSuitesCount = suites.length - ranCount;
  const passedTotal = suites.reduce((sum, s) => sum + s.passed, 0);
  const failedTotal = suites.reduce((sum, s) => sum + s.failed, 0);
  const partial = only !== null && suites.some((s) => !only.has(s.suite));
  return {
    spec: SUMMARY_JSON_SPEC,
    tool: SUMMARY_JSON_TOOL,
    exit,
    partial,
    only: only === null ? null : [...only],
    faults: [...faults],
    totals: {
      suites: suites.length,
      ran: ranCount,
      skipped_suites: skippedSuitesCount,
      controls: tally.total,
      passed: passedTotal,
      failed: failedTotal,
      skipped: skips.length,
      holes: holes.length,
    },
    suites,
    skips,
    holes,
  };
}

function writeSummaryJson(path: string, doc: SelftestSummaryJson): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(doc, null, 2)}\n`);
}

const SUMMARY_CLAUSE_SUITES: ReadonlyArray<readonly [string, readonly string[]]> = [
  ['raster-op', ['raster-components', 'raster-morph', 'raster-blur', 'raster-resize', 'raster-warp', 'raster-poly', 'raster-composite']],
  ['codec', ['png']],
  ['wrapper-reader', ['layers-wrapper']],
  ['PSD-reader', ['layers-psd']],
  ['config', ['config']],
  ['parts.json', ['parts']],
  ['sheet', ['sheet']],
  ['CLI', ['cli']],
  ['assemble', ['assemble']],
  ['plausibility', ['plausibility']],
  ['propose', ['propose']],
  ['keypoints', ['keypoints']],
  ['painting', ['painting']],
  ['structure', ['structure']],
  ['diagnostics', ['diagnostics']],
  ['rig', ['rig']],
  ['chain-inherit', ['chain-inherit']],
  ['contour-mesh', ['contour']],
  ['contour-wiring', ['contour-wiring']],
  ['auto-mesh', ['auto-mesh']],
  ['check', ['check']],
  ['requirements', ['requirements']],
  ['loop-encoder', ['loop']],
  ['skeleton', ['skeleton']],
  ['inputs', ['inputs']],
  ['fetch-examples', ['fetch-examples']],
  ['prompt', ['prompt']],
  ['comfy-adapter', ['comfy']],
  ['build', ['build']],
  ['scene', ['scene']],
  ['tree', ['tree']],
  ['tally', ['run-tally']],
  ['corpus', ['corpus']],
  ['example-propose', ['propose-corpus']],
  ['assemble-example', ['assemble-examples']],
  ['example-inputs', ['inputs-examples']],
  ['example-auto-mesh', ['auto-mesh-examples']],
  ['example-chain', ['chain']],
  ['readme-loop', ['readme-loop']],
];

/** Where a `SelftestSummaryJson` disagrees with its `RunTally`, the printed summary/PARTIAL lines, or the exit code (issue #725). */
function summaryAgreementFaults(
  doc: SelftestSummaryJson,
  tally: RunTally | null,
  printedOut: string,
  printedErr: string,
  expectedExit: number | null,
): string[] {
  const faults: string[] = [];
  if (doc.spec !== SUMMARY_JSON_SPEC) faults.push(`summary JSON spec=${JSON.stringify(doc.spec)}, required ${JSON.stringify(SUMMARY_JSON_SPEC)}`);
  if (doc.tool !== SUMMARY_JSON_TOOL) faults.push(`summary JSON tool=${JSON.stringify(doc.tool)}, required ${JSON.stringify(SUMMARY_JSON_TOOL)}`);
  if (expectedExit !== null && doc.exit !== expectedExit) {
    faults.push(`summary JSON exit=${doc.exit} disagrees with process exit ${expectedExit}`);
  }
  const bySuite = new Map(doc.suites.map((s) => [s.suite, s]));
  const sumControls = doc.suites.reduce((sum, s) => sum + s.controls, 0);
  const sumPassed = doc.suites.reduce((sum, s) => sum + s.passed, 0);
  const sumFailed = doc.suites.reduce((sum, s) => sum + s.failed, 0);
  const sumSkipped = doc.suites.reduce((sum, s) => sum + s.skipped, 0);
  const ranSuites = doc.suites.filter((s) => s.ran).map((s) => s.suite);
  const unranSuites = doc.suites.filter((s) => !s.ran).map((s) => s.suite);
  if (doc.totals.suites !== doc.suites.length) faults.push(`summary JSON totals.suites=${doc.totals.suites} disagrees with suites.length=${doc.suites.length}`);
  if (doc.totals.ran !== ranSuites.length) faults.push(`summary JSON totals.ran=${doc.totals.ran} disagrees with ran suite count ${ranSuites.length}`);
  if (doc.totals.skipped_suites !== unranSuites.length) faults.push(`summary JSON totals.skipped_suites=${doc.totals.skipped_suites} disagrees with unran suite count ${unranSuites.length}`);
  if (doc.totals.controls !== sumControls) faults.push(`summary JSON totals.controls=${doc.totals.controls} disagrees with summed suite controls ${sumControls}`);
  if (doc.totals.passed !== sumPassed) faults.push(`summary JSON totals.passed=${doc.totals.passed} disagrees with summed suite passed ${sumPassed}`);
  if (doc.totals.failed !== sumFailed) faults.push(`summary JSON totals.failed=${doc.totals.failed} disagrees with summed suite failures ${sumFailed}`);
  if (doc.totals.skipped !== sumSkipped || doc.totals.skipped !== doc.skips.length) {
    faults.push(`summary JSON totals.skipped=${doc.totals.skipped} disagrees with summed suite skips ${sumSkipped} and skips.length=${doc.skips.length}`);
  }
  if (doc.totals.holes !== doc.holes.length) faults.push(`summary JSON totals.holes=${doc.totals.holes} disagrees with holes.length=${doc.holes.length}`);

  if (tally !== null) {
    if (doc.totals.controls !== tally.total) {
      faults.push(`summary JSON totals.controls=${doc.totals.controls} disagrees with tally.total=${tally.total}`);
    }
    if (doc.suites.length !== tally.blocks.length) {
      faults.push(`summary JSON has ${doc.suites.length} suite(s); tally has ${tally.blocks.length}`);
    }
    for (let i = 0; i < Math.min(doc.suites.length, tally.blocks.length); i++) {
      const s = doc.suites[i];
      const b = tally.blocks[i];
      const bPassed = b.controls - b.fails;
      if (s.suite !== b.key || s.ran !== b.ran || s.controls !== b.controls || s.passed !== bPassed || s.failed !== b.fails || s.skipped !== b.skips.length) {
        faults.push(
          `suite "${b.key}" summary JSON has ran=${s.ran}, controls=${s.controls}, passed=${s.passed}, failed=${s.failed}, skipped=${s.skipped}; ` +
            `tally has ran=${b.ran}, controls=${b.controls}, passed=${bPassed}, failed=${b.fails}, skipped=${b.skips.length}`,
        );
      }
    }
    const tallyHoles = tally.blocks.flatMap((b) => b.skips.filter((sk) => sk.hole).map((sk) => `${b.key}:${sk.name}`));
    const jsonHoles = doc.holes.map((h) => `${h.suite}:${h.name}`);
    const missingHoles = tallyHoles.filter((h) => !jsonHoles.includes(h));
    const extraHoles = jsonHoles.filter((h) => !tallyHoles.includes(h));
    if (missingHoles.length > 0) faults.push(`summary JSON holes is missing ${missingHoles.length} hole(s) recorded by the tally: ${missingHoles.join(', ')}`);
    if (extraHoles.length > 0) faults.push(`summary JSON holes holds unexpected hole(s) not in the tally: ${extraHoles.join(', ')}`);
  }

  const outLines = printedOut.split('\n').filter((l) => l.trim() !== '');
  const greenLine = outLines.find((l) => l.startsWith('rig-parts selftest: green — ')) ?? null;
  const partialLine = outLines.find((l) => l.startsWith('rig-parts selftest: PARTIAL run ')) ?? null;
  const holeLine = outLines.find((l) => l.startsWith('  ⚠️ HOLE: ')) ?? null;

  if (greenLine !== null) {
    if (doc.partial || doc.only !== null) faults.push(`printed whole-run green summary, but summary JSON has partial=${doc.partial}, only=${JSON.stringify(doc.only)}`);
    const m = /^rig-parts selftest: green — (\d+) control\(s\) over (\d+) suite\(s\): (.+)$/.exec(greenLine);
    if (m === null) {
      faults.push(`printed green summary line did not match expected format: ${JSON.stringify(greenLine)}`);
    } else {
      const printedTotal = Number(m[1]);
      const printedRan = Number(m[2]);
      if (doc.totals.controls !== printedTotal) {
        faults.push(`printed summary total ${printedTotal} control(s) disagrees with summary JSON totals.controls=${doc.totals.controls}`);
      }
      if (doc.totals.ran !== printedRan) {
        faults.push(`printed summary ran ${printedRan} suite(s) disagrees with summary JSON totals.ran=${doc.totals.ran}`);
      }
      const clauseMap = new Map(SUMMARY_CLAUSE_SUITES);
      for (const rawClause of m[3].split(', ')) {
        const cm = /^(?:\+ )?(\d+) (\S+)$/.exec(rawClause);
        if (cm === null) {
          faults.push(`printed summary clause ${JSON.stringify(rawClause)} is not "<count> <label>"`);
          continue;
        }
        const count = Number(cm[1]);
        const label = cm[2];
        const suiteKeys = clauseMap.get(label);
        if (suiteKeys === undefined) {
          faults.push(`printed summary clause ${JSON.stringify(rawClause)} names unknown label ${JSON.stringify(label)}`);
          continue;
        }
        const jsonSum = suiteKeys.reduce((sum, k) => sum + (bySuite.get(k)?.controls ?? 0), 0);
        if (jsonSum !== count) {
          faults.push(`printed summary clause "${rawClause}" (${suiteKeys.join('+')}) disagrees with summary JSON controls=${jsonSum}`);
        }
      }
    }
    const printedHoleSuites =
      holeLine === null
        ? []
        : (/^  ⚠️ HOLE: (.+) did not run, so this run does not cover (?:it|them)\.$/.exec(holeLine)?.[1].split(', ') ?? []);
    if (printedHoleSuites.join(',') !== unranSuites.join(',')) {
      faults.push(`printed HOLE suites [${printedHoleSuites.join(', ')}] disagree with summary JSON unran suites [${unranSuites.join(', ')}]`);
    }
    for (const hs of printedHoleSuites) {
      if (!doc.holes.some((h) => h.suite === hs)) {
        faults.push(`printed HOLE line names "${hs}", which is absent from summary JSON holes`);
      }
    }
  }

  if (partialLine !== null) {
    if (!doc.partial || doc.only === null || doc.only.length === 0) {
      faults.push(`printed PARTIAL line was emitted, but summary JSON has partial=${doc.partial}, only=${JSON.stringify(doc.only)}`);
    }
    const pm = /^rig-parts selftest: PARTIAL run \(--only\) — not a verdict on the tree\. (\d+) suite\(s\) ran \[([^\]]*)\] over (\d+) case line\(s\); (\d+) suite\(s\) were not run \[([^\]]*)\]\./.exec(partialLine);
    if (pm === null) {
      faults.push(`printed PARTIAL line did not match expected format: ${JSON.stringify(partialLine)}`);
    } else {
      const pRanCount = Number(pm[1]);
      const pRanList = pm[2] === '' ? [] : pm[2].split(', ');
      const pCases = Number(pm[3]);
      const pSkipCount = Number(pm[4]);
      const pSkipList = pm[5] === '' ? [] : pm[5].split(', ');
      if (doc.totals.ran !== pRanCount || ranSuites.join(',') !== pRanList.join(',')) {
        faults.push(`printed PARTIAL ran suites (${pRanCount}: [${pRanList.join(', ')}]) disagree with summary JSON (${doc.totals.ran}: [${ranSuites.join(', ')}])`);
      }
      if (doc.totals.controls !== pCases) {
        faults.push(`printed PARTIAL case count ${pCases} disagrees with summary JSON totals.controls=${doc.totals.controls}`);
      }
      if (doc.totals.skipped_suites !== pSkipCount || unranSuites.join(',') !== pSkipList.join(',')) {
        faults.push(`printed PARTIAL skipped suites (${pSkipCount}) disagree with summary JSON (${doc.totals.skipped_suites})`);
      }
    }
  }

  if (printedErr.includes('control(s) failed') && doc.totals.failed === 0) {
    faults.push('stderr reported failed controls, but summary JSON totals.failed=0');
  }
  return faults;
}

function printGreenSummary(tally: RunTally, log: (line: string) => void = console.log): void {
  // the summary begins here
  const n = (key: string): number => tally.countOf(key);
  const raster = ['raster-components', 'raster-morph', 'raster-blur', 'raster-resize', 'raster-warp', 'raster-poly', 'raster-composite'].reduce((sum, k) => sum + n(k), 0);
  const holes = tally.blocks.filter((b) => !b.ran).map((b) => b.key);
  const ran = tally.blocks.length - holes.length;
  const corpusClause = holes.includes('corpus') ? '' : `, + ${n('corpus')} corpus`;
  const chainClause = holes.includes('chain') ? '' : `, + ${n('chain')} example-chain`;
  const readmeLoopClause = holes.includes('readme-loop') ? '' : `, + ${n('readme-loop')} readme-loop`;
  const proposeClause = holes.includes('propose-corpus') ? '' : `, + ${n('propose-corpus')} example-propose`;
  const assembleExamplesClause = holes.includes('assemble-examples') ? '' : `, + ${n('assemble-examples')} assemble-example`;
  const inputsClause = holes.includes('inputs-examples') ? '' : `, + ${n('inputs-examples')} example-inputs`;
  const autoExamplesClause = holes.includes('auto-mesh-examples') ? '' : `, + ${n('auto-mesh-examples')} example-auto-mesh`;
  log(
    `rig-parts selftest: green — ${tally.total} control(s) over ${ran} suite(s): ${raster} raster-op, + ${n('png')} codec, ` +
      `+ ${n('layers-wrapper')} wrapper-reader, + ${n('layers-psd')} PSD-reader, + ${n('config')} config, + ${n('parts')} parts.json, ` +
      `+ ${n('sheet')} sheet, + ${n('cli')} CLI, + ${n('assemble')} assemble, + ${n('plausibility')} plausibility, + ${n('propose')} propose, + ${n('keypoints')} keypoints, + ${n('painting')} painting, + ${n('structure')} structure, + ${n('diagnostics')} diagnostics, + ${n('rig')} rig, + ${n('chain-inherit')} chain-inherit, + ${n('contour')} contour-mesh, + ${n('contour-wiring')} contour-wiring, + ${n('auto-mesh')} auto-mesh, + ${n('check')} check, + ${n('requirements')} requirements, + ${n('loop')} loop-encoder, + ${n('skeleton')} skeleton, + ${n('inputs')} inputs, + ${n('fetch-examples')} fetch-examples, + ${n('prompt')} prompt, + ${n('comfy')} comfy-adapter, + ${n('build')} build, + ${n('scene')} scene, + ${n('tree')} tree, + ${n('run-tally')} tally${corpusClause}${proposeClause}${assembleExamplesClause}${inputsClause}${autoExamplesClause}${chainClause}${readmeLoopClause}`,
  );
  if (holes.length > 0) log(`  ⚠️ HOLE: ${holes.join(', ')} did not run, so this run does not cover ${holes.length === 1 ? 'it' : 'them'}.`);
  // the summary ends here
}

/**
 * The run's verdict from its suites' workers: every suite's units replayed through one tally in `keys` order, the
 * tally's own suite, the floor, and the summary. A whole run reads its live workers; a merge reads the shards' records.
 * Both print the same stdout for the same worker lines, because it is this one function.
 */
async function reportRun(
  keys: readonly string[],
  unitsOf: (key: string) => readonly string[],
  runOf: (unit: string) => Promise<WorkerRun | undefined>,
  clockText: () => string,
  cleanup: () => void,
  only: ReadonlySet<string> | null = null,
  summaryJson: string | null = null,
): Promise<void> {
  const tally = new RunTally();
  const printLine = console.log;
  console.log = (...args: unknown[]): void => {
    tally.observe(args.map((a) => (typeof a === 'string' ? a : String(a))).join(' '));
    printLine(...args);
  };
  const printErr = (text: string): void => {
    process.stderr.write(text);
  };
  // Issue #500: a suite `--only` did not name opens its section and prints one SKIP, so the floor holds it as it holds
  // any suite that did not run, and the run's suites are still every suite once and in order.
  const skipped: string[] = [];
  const skip = (key: string, why: string): void => {
    skipped.push(key);
    tally.of(key, () => {
      section(key);
      console.log(`  SKIP  ${key}: not run — ${why}`);
      return null;
    });
  };
  try {
    for (const key of keys) {
      if (only !== null && !only.has(key)) {
        skip(key, ONLY_FLAG);
        continue;
      }
      const units = unitsOf(key);
      const runs: Array<WorkerRun | undefined> = [];
      for (const unit of units) runs.push(await runOf(unit));
      tally.of(key, () => replayUnits(key, units, runs, (line) => console.log(line), printErr));
    }
  } finally {
    cleanup();
  }
  printErr(clockText());
  if (only !== null && !only.has(TALLY_SUITE)) skip(TALLY_SUITE, ONLY_FLAG);
  else if (only !== null && !tally.blocks.some((b) => b.controls > 0)) skip(TALLY_SUITE, `it measures the run it is part of, and no suite before it printed a case; name one beside it in ${ONLY_FLAG}`);
  else tally.of(TALLY_SUITE, () => runTallySuite(tally));
  console.log = printLine;

  console.log('');
  const floor = [...tallyFaults(tally.blocks, tally.gutter, tally.total), ...suiteSetFaults(tally.blocks.map((b) => b.key), [...keys, TALLY_SUITE])];
  if (floor.length > 0) {
    if (summaryJson !== null) writeSummaryJson(summaryJson, buildSummaryJson(tally, only, floor, 2));
    console.error('rig-parts selftest: this run cannot account for itself — that is not a pass, it is an empty gate');
    for (const f of floor) console.error(`  ${f}`);
    process.exit(2);
  }
  const bad = tally.failures;
  const partial = partialVerdict(
    tally.blocks.map((b) => b.key).filter((k) => !skipped.includes(k)),
    skipped,
    tally.total,
    bad,
  );
  if (partial !== null) {
    if (summaryJson !== null) writeSummaryJson(summaryJson, buildSummaryJson(tally, only, floor, partial.code));
    if (partial.err !== null) console.error(partial.err);
    console.log(partial.out);
    process.exit(partial.code);
  }
  if (bad > 0) {
    if (summaryJson !== null) writeSummaryJson(summaryJson, buildSummaryJson(tally, only, floor, 1));
    console.error(`rig-parts selftest: ${bad} control(s) failed`);
    process.exit(1);
  }
  printGreenSummary(tally);
  if (summaryJson !== null) writeSummaryJson(summaryJson, buildSummaryJson(tally, only, floor, 0));
}

/**
 * `--shard <name> --record <file>` (issue #395): run the units {@link SHARDS} gives the shard, as workers, `jobs` at a
 * time in the order listed, and write every worker's lines, result and clock to `file`. The shard judges nothing — the
 * merge does — but it prints its units' lines in run order for its own log, its clock on stderr, and exits 1 when a
 * unit wrote no result, exited non-zero or handed back a failure, so the job that ran a red unit is red too.
 */
async function shardMain(shard: string, record: string): Promise<void> {
  const mine = SHARDS.find(([n]) => n === shard)?.[1];
  if (mine === undefined) {
    console.error(`selftest: ${SHARD_FLAG} ${JSON.stringify(shard)} is no shard; the shards are ${SHARDS.map(([n]) => `"${n}"`).join(', ')}`);
    process.exit(2);
  }
  const corpus = corpusDir();
  const jobs = workerCount();
  const results = temp('workers');
  const clock = new Map<string, readonly [number, number]>();
  const t0 = performance.now();
  const runs = startWorkers(mine, jobs, async (unit) => {
    const began = performance.now() - t0;
    const run = await launchWorker(unit, corpus, results);
    clock.set(unit, [began, performance.now() - t0]);
    return run;
  });
  const done: RecordedUnit[] = [];
  try {
    for (const unit of mine) {
      const run = (await runs.get(unit)) as WorkerRun;
      const [began, ended] = clock.get(unit) ?? [0, 0];
      done.push({ ...run, began, ended });
    }
  } finally {
    rmSync(results, { recursive: true, force: true });
  }
  const units = runUnits(SUITES.map(([k]) => k), exampleKeys().all) as string[];
  const ordered = [...done].sort((a, b) => units.indexOf(a.key) - units.indexOf(b.key));
  for (const u of ordered) process.stdout.write(u.stdout);
  process.stderr.write(workerClockText(mine, clock, jobs, performance.now() - t0));
  mkdirSync(dirname(record), { recursive: true });
  const text: ShardRecord = { spec: SHARD_RECORD_SPEC, shard, jobs, cores: availableParallelism(), units: done };
  writeFileSync(record, `${JSON.stringify(text)}\n`);
  const red = done.filter((u) => {
    if (u.status !== 0 || u.result === null) return true;
    const r = JSON.parse(u.result) as { returned?: unknown; crash?: unknown };
    return typeof r.crash === 'string' || (typeof r.returned === 'number' && r.returned > 0);
  });
  if (red.length > 0) {
    console.error(`rig-parts selftest: shard ${shard}: ${red.map((u) => u.key).join(', ')} did not run green; the merge names what failed`);
    process.exit(1);
  }
}

/**
 * `--merge <dir>` (issue #395): read every shard record in `dir`, hold them together to every unit once
 * ({@link recordFaults}), then replay them through {@link reportRun} — the same tally, run-tally suite, floor and summary
 * a whole run prints, so the merged stdout is a whole run's. A record that cannot be read, or a set that is not every
 * unit once, exits 2 before anything is replayed.
 */
async function mergeMain(
  dir: string,
  keys: readonly string[],
  units: readonly string[],
  examples: readonly string[],
  summaryJson: string | null = null,
): Promise<void> {
  const files = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.json')).sort() : [];
  const records: ShardRecord[] = [];
  const faults: string[] = [];
  if (!existsSync(dir)) faults.push(`${MERGE_FLAG} names ${dir}, which does not exist, so no shard's record was read`);
  for (const f of files) {
    const r = parseShardRecord(readFileSync(join(dir, f), 'utf8'));
    if (typeof r === 'string') faults.push(`${f} is no shard record: ${r}`);
    else records.push(r);
  }
  faults.push(...recordFaults(records, SHARDS, units));
  process.stderr.write(`rig-parts selftest: merging ${records.length} shard record(s) from ${dir}: ${records.map((r) => `shard ${r.shard} (${r.units.length} unit(s), ${r.jobs} worker(s) at once on ${r.cores} core(s))`).join(', ') || 'none'}\n`);
  if (faults.length > 0) {
    console.error('rig-parts selftest: the shard records are not one run of every unit once — that is not a pass, it is an empty gate');
    for (const f of faults) console.error(`  ${f}`);
    process.exit(2);
  }
  const byUnit = new Map(records.flatMap((r) => r.units.map((u) => [u.key, { shard: r.shard, run: u }] as const)));
  const clockText = (): string => {
    const s = (ms: number): string => (ms / 1000).toFixed(1);
    const lines = ['selftest clock (stderr, never tallied): the merged shards, each unit\'s worker from its shard\'s start'];
    for (const r of records) lines.push(`  shard ${r.shard}  ${r.units.length} unit(s), ${r.jobs} worker(s) at once on ${r.cores} core(s), every worker done at ${s(Math.max(0, ...r.units.map((u) => u.ended)))} s`);
    for (const u of units) {
      const at = byUnit.get(u);
      lines.push(at === undefined ? `  clock  ${u}  not recorded` : `  clock  ${u}  ${s(at.run.ended - at.run.began)} s  (+${s(at.run.began)} .. +${s(at.run.ended)})  shard ${at.shard}`);
    }
    return `${lines.join('\n')}\n`;
  };
  await reportRun(keys, (key) => suiteUnits(key, examples), async (unit) => byUnit.get(unit)?.run, clockText, () => {}, null, summaryJson);
}

async function main(): Promise<void> {
  if (process.argv.includes(ASSEMBLE_STAGE_FLAG)) {
    assembleStageMain(process.argv.slice(2));
    return;
  }
  if (process.argv.includes(WORKER_FLAG)) {
    workerMain(process.argv);
    return;
  }
  const keys = SUITES.map(([k]) => k);
  // Issue #500: the whole command line is read before anything starts, and a word this run does not take is refused.
  const args = readRunArgs(process.argv.slice(2), RUN_FLAGS);
  if (Array.isArray(args)) refuseArgs(args);
  const shard = args.get(SHARD_FLAG) ?? null;
  const record = args.get(RECORD_FLAG) ?? null;
  const merge = args.get(MERGE_FLAG) ?? null;
  const onlyValue = args.get(ONLY_FLAG) ?? null;
  const summaryJsonArg = args.get(SUMMARY_JSON_FLAG) ?? null;
  const summaryJson = summaryJsonArg === null ? null : resolve(summaryJsonArg);
  if (onlyValue !== null && (shard !== null || merge !== null)) refuseArgs([`${ONLY_FLAG} and ${SHARD_FLAG} or ${MERGE_FLAG} each choose which suites run; give one of them`]);
  if (summaryJson !== null && shard !== null) refuseArgs([`${SUMMARY_JSON_FLAG} and ${SHARD_FLAG} cannot be combined; a shard writes ${RECORD_FLAG} and produces no run summary`]);
  const onlyRead = onlyValue === null ? null : readOnlyList(onlyValue, [...keys, TALLY_SUITE]);
  if (Array.isArray(onlyRead)) refuseArgs(onlyRead);
  const only = onlyRead;
  if (shard !== null || record !== null || merge !== null) {
    if ((shard === null) !== (record === null) || (merge !== null && shard !== null)) {
      console.error(`selftest: ${SHARD_FLAG} <name> takes ${RECORD_FLAG} <file>, and ${MERGE_FLAG} <dir> stands alone`);
      process.exit(2);
    }
    // The partition is held to every unit once before anything starts, in a shard and in the merge alike.
    const examples = exampleKeys().all;
    const units = runUnits(keys, examples);
    const partition = typeof units === 'string' ? [units] : shardFaults(SHARDS, units);
    if (typeof units === 'string' || partition.length > 0) {
      console.error('rig-parts selftest: the shards are not every unit of the run once');
      for (const f of partition) console.error(`  ${f}`);
      process.exit(2);
    }
    if (shard !== null && record !== null) await shardMain(shard, resolve(record));
    else if (merge !== null) await mergeMain(resolve(merge), keys, units, examples, summaryJson);
    return;
  }
  const corpus = corpusDir();
  const order = dispatchOrder(keys, STARTED_FIRST);
  if (typeof order === 'string') {
    console.error(`selftest: ${order}`);
    process.exit(2);
  }
  // Only the suites a partial run names get a worker; the rest are printed as skipped, in their place.
  const started = only === null ? order : order.filter((k) => only.has(k));
  const timed = only === null ? keys : keys.filter((k) => only.has(k));
  const jobs = workerCount();
  const results = temp('workers');
  const clock = new Map<string, readonly [number, number]>();
  const t0 = performance.now();
  const runs = startWorkers(started, jobs, async (key) => {
    const began = performance.now() - t0;
    const run = await launchWorker(key, corpus, results);
    clock.set(key, [began, performance.now() - t0]);
    return run;
  });
  await reportRun(
    keys,
    (key) => [key],
    (key) => runs.get(key) ?? Promise.resolve(undefined),
    () => workerClockText(timed, clock, jobs, performance.now() - t0),
    () => rmSync(results, { recursive: true, force: true }),
    only,
    summaryJson,
  );
}

const finishSelftestPeak = process.argv.includes(WORKER_FLAG) || process.argv.includes(ASSEMBLE_STAGE_FLAG) ? null : startSelftestPeak();
if (finishSelftestPeak !== null) process.on('exit', finishSelftestPeak);
await main();
finishSelftestPeak?.();
